import Navbar from "./components/Navbar";
import AboutMe from "./components/AboutMe";
import Skills from "./components/Skills";
import Projects from "./components/Projects";

function App() {
  return (
    <div className="App">
      <Navbar></Navbar>
      <AboutMe></AboutMe>
      <hr style={{ color: "white" }} />
      <Skills></Skills>
      <hr style={{ color: "white" }} />
      <Projects></Projects>
    </div>
  );
}

export default App;
